model_safe_stan:
// ForestDB translation: Inverse Statics
data {
  int<lower=1> N;
  int<lower=1> K;
  matrix[N, K] X;
  vector[N] y;
}
parameters {
  vector[K] beta;
  real<lower=0> sigma;
}
model {
  beta ~ normal(0, 5);
  sigma ~ lognormal(0, 1);
  y ~ normal(X * beta, sigma);
}
generated quantities {
  vector[N] mu = X * beta;
}
